import XCTest
@testable import Likerts

final class AdvancedQuestionsTests:XCTestCase{
  func testMobileSafeMutationsAndValidation(){XCTAssertEqual(AdvancedQuestions.move(["a","b","c"],id:"b",offset:-1),["b","a","c"]);var matrix=AdvancedQuestions.setMatrix([:],row:"r1",column:"c1",multiple:true);matrix=AdvancedQuestions.setMatrix(matrix,row:"r1",column:"c2",multiple:true);XCTAssertEqual(matrix,["r1":["c1","c2"]]);XCTAssertTrue(AdvancedQuestions.validRanking(["c","a","b"],options:["a","b","c"]));XCTAssertFalse(AdvancedQuestions.validRanking(["a","a","b"],options:["a","b","c"]));XCTAssertTrue(AdvancedQuestions.validMatrix(["r1":["c1"],"r2":["c2"]],rows:["r1","r2"],columns:["c1","c2"],multiple:false,required:true));XCTAssertTrue(AdvancedQuestions.validAllocation(["a":50,"b":50],items:["a","b"],total:100));XCTAssertEqual(AdvancedQuestions.remaining(total:100,answer:["a":25,"b":50]),25)}
  func testSharedFixtureDecodesAndFormStateEmitsExactWireAnswers()throws{let root=URL(fileURLWithPath:#filePath).deletingLastPathComponent().deletingLastPathComponent().deletingLastPathComponent().deletingLastPathComponent().deletingLastPathComponent();let source=try JSONSerialization.jsonObject(with:Data(contentsOf:root.appendingPathComponent("contracts/advanced-survey.example.json"))) as! [String:Any];let data=try JSONSerialization.data(withJSONObject:["id":"c","surveyId":"s","version":1,"placement":"p","schema":["schemaVersion":5,"title":source["title"]!,"questions":source["questions"]!]]);let collection=try JSONDecoder().decode(Collection.self,from:data);var state=SurveyFormState();state.rankings["priorities"]=["quality","speed","price"];state.matrices["experience"]=["service":["excellent"],"product":["good"]];state.allocations["investment"]=["product":50,"support":30,"marketing":20];XCTAssertNil(state.validationError(collection:collection,strings:SurveyStrings()));let encoded=try JSONSerialization.jsonObject(with:JSONEncoder().encode(Submission(idempotencyKey:"test",answers:state.answers(collection:collection)))) as! [String:Any];let answers=encoded["answers"] as! [String:Any];XCTAssertEqual(answers["priorities"] as? [String],["quality","speed","price"]);XCTAssertEqual((answers["experience"] as? [String:String])?["service"],"excellent");XCTAssertEqual((answers["investment"] as? [String:Int])?["support"],30)}
}
